// Client-side round-robin over instances resolved from the registry.
type RoundRobin struct {
	n uint64
}

// Pick returns the next instance, cycling evenly across all of them.
func (rr *RoundRobin) Pick(insts []Instance) (Instance, bool) {
	if len(insts) == 0 {
		return Instance{}, false // no live backends
	}
	// atomic so concurrent callers stay balanced
	i := atomic.AddUint64(&rr.n, 1)
	return insts[int(i)%len(insts)], true
}
